// Writes game/balanced-path.js: the Balanced player's choice for every Chapter 1 decision on the
// game's seed, for the testers' jump to a month (ruled 30 September 2026, ONBOARDING.md section 9).
//
// Balanced is the calibration harness's model of a thoughtful player (maths doc section 13). Its
// rule looks ahead to month 24 for every option, which is too slow for a phone, and the harness
// reads files the browser cannot. The game always plays one seed (game/config.js SEED), so the
// path is fixed: it is worked out here, once, and the game replays it.
//
// Re-run whenever the sheet or section 12 changes. --check fails if the file is out of date.
//
// Usage: node scripts/export_balanced_path.mjs [--check]

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { createState } from "../engine/index.js";
import { play, typePicker, CHAPTER_END } from "../calibration/harness.js";

const OUT = fileURLToPath(new URL("../game/balanced-path.js", import.meta.url));
// game/ is browser code that Node does not load as a module, so the seed is read as text
const SEED = Number(readFileSync(new URL("../game/config.js", import.meta.url), "utf8").match(/^export const SEED = (\d+);\r?$/m)[1]);

const run = play(createState(SEED), typePicker("balanced"), CHAPTER_END);
const choices = {};
for (const month of run.months) Object.assign(choices, month.chosen);

const body = JSON.stringify(Object.fromEntries(Object.entries(choices).sort()), null, 2);
const text = `// Generated by scripts/export_balanced_path.mjs. Do not edit by hand.
// The Balanced player's choice for each Chapter 1 decision on seed ${SEED}, for the testers' jump
// to a month (game/testing.js). Re-run the script when the sheet or section 12 changes.

export const BALANCED_CHOICES = Object.freeze(${body});
`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8");
  } catch (whatever) {
    // missing counts as out of date
  }
  // Line endings aside: a Windows checkout may have turned them into CRLF
  if (current.replace(/\r\n/g, "\n") !== text) {
    console.error("game/balanced-path.js is out of date. Run: node scripts/export_balanced_path.mjs");
    process.exit(1);
  }
  console.log(`game/balanced-path.js is current: ${Object.keys(choices).length} decisions.`);
} else {
  writeFileSync(OUT, text);
  console.log(`Wrote ${Object.keys(choices).length} Balanced choices to game/balanced-path.js`);
}
